from datetime import date, timedelta


def _is_workday(day, holidays):
    return day.weekday() < 5 and day not in holidays


def add_workdays(start, days, holidays=()):
    """Move by working days, rolling a nonworking start forward for zero."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an int")
    holidays = set(holidays or ())
    if days == 0 and _is_workday(start, holidays):
        return start

    step = timedelta(days=-1 if days < 0 else 1)
    remaining = max(1, abs(days))
    while remaining:
        start += step
        if _is_workday(start, holidays):
            remaining -= 1
    return start


def count_workdays(first, last, holidays=()):
    """Count working days inclusively, negating the count for reversed dates."""
    sign = 1
    if first > last:
        first, last = last, first
        sign = -1
    holidays = set(holidays or ())
    return sign * sum(
        _is_workday(date.fromordinal(ordinal), holidays)
        for ordinal in range(first.toordinal(), last.toordinal() + 1)
    )
